import{_ as o,o as e,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Implementing a Resilient Ceph RGW Object Storage with Erasure Coded Data Pool as the Foundation...","description":"","frontmatter":{"title":"Implementing a Resilient Ceph RGW Object Storage with Erasure Coded Data Pool as the Foundation...","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Object Storage","Erasure Coding","High Availability","Cloud Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Implementing_a_Resilient_Ceph_RGW_Object_Storage_with_Erasure_Coded_Data_Pool_as_the_Foundation....md","filePath":"posts/2023/Implementing_a_Resilient_Ceph_RGW_Object_Storage_with_Erasure_Coded_Data_Pool_as_the_Foundation....md","lastUpdated":1780459816000}'),s={name:"posts/2023/Implementing_a_Resilient_Ceph_RGW_Object_Storage_with_Erasure_Coded_Data_Pool_as_the_Foundation....md"};function r(l,t,a,_,g,p){return e(),i("div",null,[...t[0]||(t[0]=[n("<p>在本次会议中，Digicolor的云工程师Bahid分享了公司设计和实施对象存储服务的经验。由于主要发言人Yavash无法到场，其演讲以预录视频形式进行。</p><p><strong>主要议题包括</strong>：</p><ol><li><strong>公司概况</strong>：Digicolor是中东地区最大的电子商务平台，日均页面浏览量超过1800万，促销期间可达2亿。</li><li><strong>问题定义</strong>：面临高流量和高数据存储需求，原有硬件资源共享导致成本上升。</li><li><strong>解决方案</strong>：设计并实施自有的对象存储服务，以降低成本并提高性能。</li><li><strong>技术细节</strong>： <ul><li><strong>架构设计</strong>：采用三层架构，包括Nginx作为缓存服务器和负载均衡器，Ceph RGW处理对象存储。</li><li><strong>硬件环境</strong>：利用闲置硬件资源，部署8个节点，使用HP 10G网络设备。</li><li><strong>软件环境</strong>：测试了Octopus和Pacific版本的Ceph，使用Ubuntu LTS和OpenResty构建模块。</li><li><strong>性能优化</strong>：通过自定义CRUSH映射、使用SSD作为后端存储、分离公共和集群网络等措施优化性能。</li><li><strong>数据缓存</strong>：设计了多层缓存机制，包括CDN、图像大小调整和Nginx缓存。</li></ul></li><li><strong>测试与结果</strong>： <ul><li><strong>负载测试</strong>：使用Locust框架和实际图像数据进行测试，设计了两种场景以模拟真实流量。</li><li><strong>性能指标</strong>：通过基准测试，选择了Azure RBD以提高存储容量和性能。</li><li><strong>最终配置</strong>：确定了9个RGW实例，每个实例的线程池大小为2008和2048，以优化CPU核心分配。</li></ul></li></ol><p><strong>决定事项</strong>：</p><ol><li><strong>采用Ceph RGW作为对象存储服务</strong>。</li><li><strong>优化Nginx配置和RGW实例数量</strong>。</li><li><strong>实施多层缓存策略以提高性能</strong>。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li><strong>继续监控和优化系统性能</strong>。</li><li><strong>探索更多性能优化技术，如进一步调整CRUSH映射和网络配置</strong>。</li><li><strong>分享经验和技术细节，与社区进行交流</strong>。</li></ol><p>Digicolor通过设计和实施自有的对象存储服务，成功降低了成本并提高了系统性能，满足了公司的高流量和高存储需求。会议最后，Bahid邀请与会者提问，并表示愿意分享更多细节和经验。</p>",8)])])}const c=o(s,[["render",r]]);export{u as __pageData,c as default};
